import{_ as t,c as r,o,ae as a}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Configuration Values","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"values-section","title":"Values — a whole section","description":"Effective values for every field under sales.order_settings.","query":"curl -X GET \\"https://your-domain.com/api/admin/configuration?slug=sales.order_settings&channel=default&locale=en\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"slug\\": \\"sales.order_settings\\",\\n    \\"channel\\": \\"default\\",\\n    \\"locale\\": \\"en\\",\\n    \\"values\\": {\\n      \\"sales.order_settings.order_number.order_number_prefix\\": null,\\n      \\"sales.order_settings.order_number.order_number_length\\": null,\\n      \\"sales.order_settings.order_number.order_number_suffix\\": null,\\n      \\"sales.order_settings.order_number.order_number_generator\\": null,\\n      \\"sales.order_settings.minimum_order.enable\\": null,\\n      \\"sales.order_settings.minimum_order.minimum_order_amount\\": null,\\n      \\"sales.order_settings.minimum_order.include_discount_amount\\": null,\\n      \\"sales.order_settings.minimum_order.include_tax_to_amount\\": null,\\n      \\"sales.order_settings.minimum_order.description\\": null,\\n      \\"sales.order_settings.reorder.admin\\": \\"1\\",\\n      \\"sales.order_settings.reorder.shop\\": \\"0\\"\\n    }\\n  }\\n]\\n"},{"id":"values-group","title":"Values — a single group","description":"Narrow the slug to one group to read just those fields.","query":"curl -X GET \\"https://your-domain.com/api/admin/configuration?slug=sales.order_settings.reorder&channel=default&locale=en\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"[\\n  {\\n    \\"slug\\": \\"sales.order_settings.reorder\\",\\n    \\"channel\\": \\"default\\",\\n    \\"locale\\": \\"en\\",\\n    \\"values\\": {\\n      \\"sales.order_settings.reorder.admin\\": \\"1\\",\\n      \\"sales.order_settings.reorder.shop\\": \\"0\\"\\n    }\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/configuration/values.md","filePath":"api/rest-api/admin/configuration/values.md"}'),n={name:"api/rest-api/admin/configuration/values.md"};function s(d,e,l,i,u,c){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="configuration-values" tabindex="-1">Configuration Values <a class="header-anchor" href="#configuration-values" aria-label="Permalink to &quot;Configuration Values&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/configuration?slug=&lt;…&gt;</code></td><td>GET</td></tr></tbody></table><p>Returns the flat <code>code → value</code> map of effective values for every field under the given <code>slug</code>. A field with no saved value falls back to the schema <code>default</code> reported by the <a href="./menu.html">Menu</a> endpoint. See the <a href="./">Configuration overview</a> for the full read → write flow.</p><p>The response is a one-element array; the object inside carries <code>slug</code>, <code>channel</code>, <code>locale</code>, and the <code>values</code> map.</p><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>slug</code></td><td>string</td><td><strong>Required.</strong> The <code>section.group</code> (or deeper) scope to read, e.g. <code>sales.order_settings</code>.</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code for resolution. Defaults to the requested channel.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code for resolution. Defaults to the requested locale.</td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response shape&quot;">​</a></h2><p><code>values</code> is a string → string map — the underlying store column is text, so booleans, numbers, and JSON all come back as strings (<code>&quot;1&quot;</code>, <code>&quot;0&quot;</code>, <code>&quot;49.99&quot;</code>). <code>image</code> / <code>file</code> fields return the storage path written by Update.</p><h2 id="response-codes" tabindex="-1">Response codes <a class="header-anchor" href="#response-codes" aria-label="Permalink to &quot;Response codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>200</td><td>Values returned.</td></tr><tr><td>401</td><td>Unauthenticated.</td></tr><tr><td>404</td><td>Slug not registered.</td></tr><tr><td>422</td><td><code>slug</code> query parameter missing.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">slug is required</p><p>The <code>slug</code> parameter is mandatory — it prevents accidentally dumping the entire configuration store in one call.</p></div><div class="tip custom-block"><p class="custom-block-title">Scope is per-field</p><p>Whether <code>channel</code> / <code>locale</code> change the result depends on each field&#39;s <code>channelBased</code> / <code>localeBased</code> flags (see <a href="./menu.html">Menu</a>). A global field returns the same value regardless of the channel / locale you pass.</p></div>',12)]))}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
